package com.coffeeshop.service;
import com.coffeeshop.dto.TableManagementCommands;import com.coffeeshop.model.TableManagementModels;import com.coffeeshop.repository.TableManagementRepository;import org.junit.jupiter.api.Test;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ReservationServiceTest{private final Stub repository=new Stub();private final TableManagementService service=new TableManagementService(repository);@Test void normalizesAndSavesReservation(){long id=service.saveReservation(command(null,1," Guest ",2,"PENDING",null));assertEquals(9,id);assertEquals("Guest",repository.saved.guestName());}@Test void validatesTableGuestTimePartyAndStatus(){assertThrows(IllegalArgumentException.class,()->service.saveReservation(command(null,0,"Guest",2,"PENDING",null)));assertThrows(IllegalArgumentException.class,()->service.saveReservation(command(null,1," ",2,"PENDING",null)));assertThrows(IllegalArgumentException.class,()->service.saveReservation(command(null,1,"Guest",0,"PENDING",null)));assertThrows(IllegalArgumentException.class,()->service.saveReservation(command(null,1,"Guest",2,"INVALID",null)));}@Test void requiresVersionWhenEditing(){assertThrows(IllegalArgumentException.class,()->service.saveReservation(command(1L,1,"Guest",2,"CONFIRMED",null)));}@Test void returnsReservationHistory(){repository.reservations=List.of(new TableManagementModels.Reservation(1,"RSV1",1,"Table 1",null,"Guest",null,null,LocalDateTime.now(),2,"PENDING",null,new byte[]{1}));assertEquals(1,service.reservations().size());}private static TableManagementCommands.SaveReservation command(Long id,long table,String guest,int party,String status,byte[]version){return new TableManagementCommands.SaveReservation(id,table,null,guest,null,null,LocalDateTime.now().plusDays(1),party,status,null,version);}private static final class Stub implements TableManagementRepository{TableManagementCommands.SaveReservation saved;List<TableManagementModels.Reservation>reservations=List.of();public List<TableManagementModels.CafeTable>tables(){return List.of();}public List<TableManagementModels.Reservation>reservations(){return reservations;}public long saveTable(TableManagementCommands.SaveTable q){return 1;}public void setTableActive(long id,boolean active,byte[]version){}public long saveReservation(TableManagementCommands.SaveReservation q){saved=q;return 9;}}
}
